    private void scheduleRefresh(){if(!refreshQueued){refreshQueued=true;handler.postDelayed(refresh,350);}}
    private void page(int index){saveDraft();selected=index;chat=null;choosing=null;query="";listLimit=100;buildPage();}
    private void buildPage(){
        if(mapPanel!=null){mapPanel.destroy();mapPanel=null;}body.removeAllViews();nav.removeAllViews();composer=null;search=null;results=null;scroll=null;chatStatus=null;sendButton=null;
        for(int i=0;i<pages.length;i++){final int index=i;LinearLayout item=column();item.setGravity(Gravity.CENTER);TextView icon=text(symbols[i],23,i==selected?ORANGE:MUTED);icon.setGravity(Gravity.CENTER);item.addView(icon);TextView label=text(pages[i],10,i==selected?ORANGE:MUTED);label.setGravity(Gravity.CENTER);item.addView(label);item.setMinimumHeight(dp(56));item.setContentDescription(pages[i]);item.setFocusable(true);item.setOnClickListener(v->page(index));nav.addView(item,new LinearLayout.LayoutParams(0,-1,1));}
        if(selected==4){map();return;}
        if(chat!=null&&selected==3){chatPage();return;}
        if(selected>=1&&selected<=3){LinearLayout tools=column();tools.setPadding(dp(16),dp(12),dp(16),dp(8));TextView h=text(pages[selected],24,WHITE);h.setTypeface(null,Typeface.BOLD);tools.addView(h);LinearLayout filters=row();String[] labels={"All","Meshtastic","MeshCore"};for(int i=0;i<3;i++){final int choice=i;Button b=button(labels[i],()->{filter=choice;buildPage();});b.setTextColor(i==filter?WHITE:ORANGE);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(48),1);p.setMargins(0,dp(8),dp(5),0);filters.addView(b,p);}tools.addView(filters);search=new EditText(this);search.setTextColor(WHITE);search.setHintTextColor(MUTED);search.setTextSize(14);search.setHint("Search "+pages[selected].toLowerCase(Locale.ROOT));search.setSingleLine(true);search.setText(query);search.addTextChangedListener(watcher(()->{query=search.getText().toString();listLimit=100;refreshContent();}));tools.addView(search,new LinearLayout.LayoutParams(-1,dp(48)));LinearLayout extra=row();
            if(selected==1){Button favorite=button(favoritesOnly?"★ Favorites":"☆ Favorites",()->{favoritesOnly=!favoritesOnly;buildPage();});extra.addView(favorite,new LinearLayout.LayoutParams(0,dp(44),1));extra.addView(button(new String[]{"Recent","Name","Distance"}[nodeOrder],()->{nodeOrder=(nodeOrder+1)%3;if(nodeOrder==2&&position.location==null)requestPhonePosition();refreshContent();}),new LinearLayout.LayoutParams(0,dp(44),1));}
            if(selected==3){extra.addView(button(unreadOnly?"Unread ✓":"Unread",()->{unreadOnly=!unreadOnly;buildPage();}),new LinearLayout.LayoutParams(0,dp(44),1));extra.addView(button(pinnedOnly?"Pinned ✓":"Pinned",()->{pinnedOnly=!pinnedOnly;buildPage();}),new LinearLayout.LayoutParams(0,dp(44),1));}
            tools.addView(extra);body.addView(tools);}
        scroll=new ScrollView(this);results=column();results.setPadding(dp(16),dp(16),dp(16),dp(20));scroll.addView(results);body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));refreshContent();
    }
    private boolean included(RadioProfile p){return filter==0||filter==p.ordinal()+1;}
    private boolean matches(String value){return value.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT));}
    private Snapshot snapshot(RadioProfile p){return service==null?Snapshot.empty():service.data(p);}
    private String radio(RadioProfile p){return service==null?"":service.sessions.get(p).address;}
    private boolean ready(RadioProfile p,String address){return service!=null&&service.sessions.get(p).verified&&radio(p).equals(address);}
    private void refreshContent(){
        if(dualStatus!=null&&service!=null){android.text.SpannableStringBuilder summary=new android.text.SpannableStringBuilder();for(RadioProfile p:RadioProfile.values()){if(summary.length()>0)summary.append("    ·    ");int begin=summary.length();RadioService.Session session=service.sessions.get(p);summary.append(p==RadioProfile.MESHTASTIC?"MT ":"MC ").append(session.verified?"ready":session.desired?session.phase.toLowerCase(Locale.ROOT):"offline").append(" · ").append(Integer.toString(snapshot(p).unread())).append(" unread");summary.setSpan(new android.text.style.ForegroundColorSpan(p==RadioProfile.MESHTASTIC?ORANGE:MapPanel.MC),begin,summary.length(),0);}dualStatus.setText(summary);}
        if(mapPanel!=null)mapPanel.update();
        if(results==null)return;int y=scroll==null?0:scroll.getScrollY();boolean bottom=scroll!=null&&(results.getHeight()-scroll.getHeight()-y<dp(80));results.removeAllViews();
        if(service!=null&&!service.history.error.isEmpty())results.addView(text(service.history.error,14,RED));
        if(chat!=null&&selected==3){messages();if(scroll!=null)scroll.post(()->{if(scroll!=null)scroll.scrollTo(0,bottom?results.getHeight():y);});return;}
        if(selected==0)home();else if(selected==5)settings();else lists();
        if(scroll!=null)scroll.post(()->{if(scroll!=null)scroll.scrollTo(0,y);});
    }
    private void home(){title(results,"Two networks. One view.","Independent radios, one inbox and one map.");LinearLayout combined=card(results);int ready=0,unread=0;for(RadioProfile p:RadioProfile.values()){if(ready(p,radio(p)))ready++;unread+=snapshot(p).unread();}combined.addView(text(ready+" / 2 networks ready · "+unread+" unread",18,WHITE));addButton(combined,"All conversations",()->{filter=0;page(3);});addButton(combined,"Connect saved radios",()->withPermission(()->service.connectSaved()));for(RadioProfile p:RadioProfile.values()){
        RadioService.Session s=service==null?null:service.sessions.get(p);Snapshot data=snapshot(p);LinearLayout c=card(results);TextView h=text(p.title,21,WHITE);h.setTypeface(null,Typeface.BOLD);c.addView(h);space(c,8);c.addView(text(s==null?"○ Offline":s.verified?"● Ready":s.connected?"● Synchronizing":"○ Offline",14,s!=null&&s.verified?GREEN:ORANGE));space(c,6);c.addView(text(s==null?"Choose a radio in Settings":s.status,13,MUTED));space(c,10);c.addView(text(data.nodes.size()+" nodes • "+data.channels.stream().filter(ch->ch.enabled).count()+" channels • "+data.unread()+" unread",14,WHITE));if(s!=null&&!s.name.isEmpty()){space(c,6);c.addView(text(s.name+" • "+s.frames+" frames received",12,MUTED));}addButton(c,"Open "+p.title+" chats",()->{filter=p.ordinal()+1;page(3);});addButton(c,"Manage radio",()->{selected=5;choosing=p;buildPage();});}
        LinearLayout note=card(results);note.addView(text("Field alpha • 0.3.0",16,ORANGE));space(note,8);note.addView(text("History and drafts stay on this phone. Radio acceptance is different from a recipient delivery confirmation. The map combines both networks; phone GPS and POIs stay local. Track recording remains planned.",14,MUTED));}
    private void lists(){
        int shown=0;
        if(selected==1){ArrayList<MapPanel.Located> nodes=mapNodes();nodes.removeIf(ref->!included(ref.profile)||!matches(nodeName(ref.profile,ref.node)+" "+ref.node.id)||(favoritesOnly&&!ref.favorite));
            nodes.sort((a,b)->{if(a.favorite!=b.favorite)return a.favorite?-1:1;if(nodeOrder==1)return nodeName(a.profile,a.node).compareToIgnoreCase(nodeName(b.profile,b.node));if(nodeOrder==2&&position.location!=null)return Double.compare(nodeDistance(a.node),nodeDistance(b.node));return Long.compare(b.node.heard,a.node.heard);});
            for(MapPanel.Located ref:nodes){if(shown++>=listLimit)continue;Node n=ref.node;LinearLayout c=card(results);c.addView(text((ref.favorite?"★ ":"")+nodeName(ref.profile,n),18,WHITE));space(c,6);c.addView(text(ref.profile.title+" · "+ago(n.heard)+distanceText(n)+(n.battery>=0?" · battery "+n.battery+"%":""),12,ref.profile==RadioProfile.MESHTASTIC?ORANGE:MapPanel.MC));c.setOnClickListener(v->nodeDetails(ref.profile,n));c.setFocusable(true);}
        }else if(selected==2){for(RadioProfile p:RadioProfile.values())if(included(p))for(Channel channel:snapshot(p).channels){if(!channel.enabled||!matches(channel.name))continue;if(shown++>=listLimit)continue;LinearLayout c=card(results);c.addView(text(channel.name,18,WHITE));space(c,6);c.addView(text(p.title+" · channel "+channel.slot+(ready(p,radio(p))?"":" · saved"),12,p==RadioProfile.MESHTASTIC?ORANGE:MapPanel.MC));addButton(c,"Open conversation",()->openChat(p,radio(p),Target.channel(channel)));}
        }else{EnumMap<RadioProfile,Snapshot> snapshots=new EnumMap<>(RadioProfile.class);EnumMap<RadioProfile,String> radios=new EnumMap<>(RadioProfile.class);for(RadioProfile p:RadioProfile.values()){snapshots.put(p,snapshot(p));radios.put(p,radio(p));}
            for(UiFeed.Item item:UiFeed.conversations(snapshots,radios,filter,unreadOnly,pinnedOnly,query)){Conversation conversation=item.conversation;if(shown++>=listLimit)continue;LinearLayout c=card(results);c.addView(text((conversation.pinned?"★ ":"")+conversation.target.title+(conversation.unread>0?" · "+conversation.unread+" unread":"")+(conversation.muted?" · muted":""),18,conversation.unread>0?ORANGE:WHITE));space(c,6);TextView preview=text(conversation.last.body,14,MUTED);preview.setMaxLines(2);c.addView(preview);space(c,6);c.addView(text(item.profile.title+" · "+when(conversation.last.timestamp),12,item.profile==RadioProfile.MESHTASTIC?ORANGE:MapPanel.MC));c.setOnClickListener(v->openChat(item.profile,item.radio,conversation.target));c.setOnLongClickListener(v->{conversationOptions(item.profile,item.radio,conversation.target);return true;});c.setFocusable(true);}
        }
        if(shown>listLimit)addButton(results,"Show more results ("+shown+" total)",()->{listLimit+=100;refreshContent();});
        if(shown==0){LinearLayout c=card(results);c.addView(text("No matching "+pages[selected].toLowerCase(Locale.ROOT),20,ORANGE));space(c,8);c.addView(text(selected==3?"Open a channel in Groups or a client in Nodes to start a conversation.":"Connect a radio and wait for synchronization. Saved data remains available offline.",14,MUTED));}
        if(selected==3&&service!=null){results.addView(text("Showing up to "+service.history.historyLimit+" recent messages per radio.",12,MUTED));if(service.history.historyLimit<20000)addButton(results,"Load older messages",()->service.history.older());}
    }
    ArrayList<MapPanel.Located> mapNodes(){ArrayList<MapPanel.Located> nodes=new ArrayList<>();for(RadioProfile p:RadioProfile.values())for(Node n:snapshot(p).nodes)nodes.add(new MapPanel.Located(p,radio(p),n,snapshot(p).flags("node",n.id).favorite));return nodes;}
    private double nodeDistance(Node n){return position.location==null||System.currentTimeMillis()-position.location.getTime()>120000||!n.position?Double.POSITIVE_INFINITY:GeoMath.distance(position.location.getLatitude(),position.location.getLongitude(),n.lat,n.lon);}
    private String distanceText(Node n){double meters=nodeDistance(n);return Double.isFinite(meters)?String.format(Locale.ROOT," · %.1f km",meters/1000):"";}
    private String nodeName(RadioProfile p,Node n){if(!n.name.isEmpty())return n.name;return p==RadioProfile.MESHTASTIC?String.format(Locale.ROOT,"!%08x",Long.parseLong(n.id)):n.id.substring(0,Math.min(12,n.id.length()));}
    private void nodeDetails(RadioProfile p,Node n){String radio=radio(p);boolean favorite=snapshot(p).flags("node",n.id).favorite;String[] actions=n.position?new String[]{"Node information","Message",favorite?"Remove favorite":"Add favorite","Show on map"}:new String[]{"Node information","Message",favorite?"Remove favorite":"Add favorite"};new AlertDialog.Builder(this).setTitle(p.title+" · "+nodeName(p,n)).setItems(actions,(dialog,action)->{
        if(action==0)new AlertDialog.Builder(this).setTitle(nodeName(p,n)).setMessage(p.title+"\n"+n.id+"\nLast heard: "+when(n.heard)+distanceText(n)+(n.battery>=0?"\nBattery: "+n.battery+"%":"")+(n.position?String.format(Locale.ROOT,"\nPosition: %.6f, %.6f",n.lat,n.lon):"")).setPositiveButton("Close",null).show();
        else if(action==1){if(n.unmessagable||(p==RadioProfile.MESHCORE&&n.type!=1))Toast.makeText(this,"Direct chat requires a message-capable client contact",Toast.LENGTH_LONG).show();else openChat(p,radio,Target.node(n));}
        else if(action==2&&service!=null)service.history.flag(p,radio,"node",n.id,"favorite",!favorite);
        else if(action==3)showMap(n.lat,n.lon);
    }).setNegativeButton("Close",null).show();}
    void showMap(double lat,double lon){mapFocus=new org.maplibre.android.geometry.LatLng(lat,lon);page(4);}
    private void conversationOptions(RadioProfile p,String radio,Target target){Flags flags=snapshot(p).flags("chat",target.topic);new AlertDialog.Builder(this).setTitle(p.title+" · "+target.title).setItems(new String[]{flags.pinned?"Unpin conversation":"Pin conversation",flags.muted?"Unmute notifications":"Mute notifications"},(d,index)->{if(service!=null)service.history.flag(p,radio,"chat",target.topic,index==0?"pinned":"muted",index==0?!flags.pinned:!flags.muted);}).setNegativeButton("Close",null).show();}
    private void openChat(RadioProfile p,String radio,Target target){saveDraft();selected=3;chatProfile=p;chatRadio=radio;chat=target;chatLimit=100;buildPage();}
    private String draftKey(){return chatProfile+"|"+chatRadio+"|"+(chat==null?"":chat.topic);}
    private void saveDraft(){handler.removeCallbacks(saveDraftTask);if(chat==null||composer==null)return;String value=composer.getText().toString();drafts.put(draftKey(),value);if(service!=null)service.history.draft(chatProfile,chatRadio,chat.topic,value);}
    private void applyDraft(String value){applyingDraft=true;composer.setText(value);applyingDraft=false;}
    private void loadDraft(){
        if(chat==null||composer==null||service==null)return;final String key=draftKey();
        if(drafts.containsKey(key)){applyDraft(drafts.get(key));return;}
        final EditText editor=composer;final int revision=composerRevision;
        service.history.loadDraft(chatProfile,chatRadio,chat.topic,value->{
            if(chat!=null&&key.equals(draftKey())&&composer==editor&&composerRevision==revision&&!drafts.containsKey(key))applyDraft(value);
        });
    }
    private void chatPage(){LinearLayout h=column();h.setPadding(dp(16),dp(8),dp(16),dp(8));h.addView(button("‹ Conversations",()->{saveDraft();chat=null;buildPage();}));TextView title=text(chat.title,21,WHITE);title.setTypeface(null,Typeface.BOLD);h.addView(title);chatStatus=text(chatProfile.title,12,MUTED);h.addView(chatStatus);h.addView(button("Conversation options",()->conversationOptions(chatProfile,chatRadio,chat)));body.addView(h);
        scroll=new ScrollView(this);results=column();results.setPadding(dp(16),dp(12),dp(16),dp(12));scroll.addView(results);body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout entry=column();entry.setPadding(dp(12),dp(6),dp(12),dp(8));entry.setBackgroundColor(PANEL);composer=new EditText(this);composer.setTextColor(WHITE);composer.setHintTextColor(MUTED);composer.setHint("Write a message…");composer.setTextSize(15);composer.setMinLines(1);composer.setMaxLines(4);composer.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);composer.setFilters(new InputFilter[]{new InputFilter.LengthFilter(1000)});entry.addView(composer,new LinearLayout.LayoutParams(-1,-2));LinearLayout controls=row();count=text("0 bytes",12,MUTED);controls.addView(count,new LinearLayout.LayoutParams(0,-2,1));sendButton=button("Send",this::send);controls.addView(sendButton,new LinearLayout.LayoutParams(dp(112),dp(48)));controls.addView(button("Replies",this::quickReply));entry.addView(controls);body.addView(entry);
        composer.addTextChangedListener(watcher(()->{composerRevision++;drafts.put(draftKey(),composer.getText().toString());updateComposer();if(!applyingDraft){handler.removeCallbacks(saveDraftTask);handler.postDelayed(saveDraftTask,500);}}));if(drafts.containsKey(draftKey()))applyDraft(drafts.get(draftKey()));loadDraft();refreshContent();scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));}
    private void updateComposer(){if(composer==null)return;int size=composer.getText().toString().getBytes(StandardCharsets.UTF_8).length;count.setText(size+" UTF-8 bytes");sendButton.setEnabled(!sending&&ready(chatProfile,chatRadio)&&size>0);sendButton.setText(sending?"Saving…":"Send");}
    private void send(){if(service==null||chat==null||sending)return;final String value=composer.getText().toString(),key=draftKey();saveDraft();sending=true;updateComposer();withPermission(()->service.send(chatProfile,chatRadio,chat,value,error->{sending=false;if(!error.isEmpty())Toast.makeText(this,error,Toast.LENGTH_LONG).show();else if(chat!=null&&key.equals(draftKey())&&composer!=null&&composer.getText().toString().equals(value)){composer.setText("");saveDraft();}else if(chat!=null&&key.equals(draftKey()))saveDraft();updateComposer();scheduleRefresh();}));}
    private void messages(){
        ArrayList<Message> visibleMessages=new ArrayList<>();if(radio(chatProfile).equals(chatRadio))for(Message m:snapshot(chatProfile).messages)if(m.topic.equals(chat.topic))visibleMessages.add(m);
        if(visibleMessages.size()>chatLimit)addButton(results,"Show earlier messages",()->{chatLimit+=100;refreshContent();});
        boolean connected=ready(chatProfile,chatRadio);chatStatus.setText(chatProfile.title+" • "+(connected?"ready":"offline / synchronizing • draft stays here"));updateComposer();int shown=0;boolean unread=false;
        for(Message m:visibleMessages.subList(Math.max(0,visibleMessages.size()-chatLimit),visibleMessages.size())){shown++;LinearLayout c=card(results);c.setBackground(surface(m.outgoing?PANEL2:PANEL));TextView author=text(m.outgoing?"You":m.sender,13,m.outgoing?ORANGE:GREEN);author.setTypeface(null,Typeface.BOLD);c.addView(author);space(c,6);TextView body=text(m.body,16,WHITE);body.setTextIsSelectable(true);c.addView(body);space(c,8);c.addView(text(when(m.timestamp)+(m.outgoing?" • "+deliveryLabel(m.state):""),11,m.state.equals("delivered")?GREEN:m.state.equals("rejected")?RED:MUTED));if(!m.read&&!m.outgoing)unread=true;}
        if(shown==0)results.addView(text("No messages in this conversation yet. Your draft is saved automatically.",14,MUTED));
        if(unread&&visible&&service!=null)service.history.read(chatProfile,chatRadio,chat.topic);
    }
    static String deliveryLabel(String state){switch(state){case "queued":return "Saved / queued";case "submitted":return "Submitted over Bluetooth";case "radio accepted":return "Accepted by radio";case "delivered":return "Recipient acknowledged";case "rejected":return "Rejected";case "uncertain":return "Delivery unknown • no automatic resend";default:return state;}}
    private void settings(){title(results,"Radio connections","Disconnect the older Alpha app before pairing here. Each radio keeps its own connection.");if(service!=null){Switch auto=new Switch(this);auto.setText("Automatic reconnection");auto.setTextColor(WHITE);auto.setChecked(service.autoReconnect);auto.setOnCheckedChangeListener((b,on)->service.setAutoReconnect(on));results.addView(auto);space(results,16);}
        if(choosing!=null){LinearLayout c=card(results);c.addView(text("Choose "+choosing.title+" radio",19,WHITE));space(c,8);c.addView(text("Close other mesh apps first. Android handles pairing and PIN prompts.",13,MUTED));RadioProfile target=choosing;addButton(c,service!=null&&service.scanning?"Stop scan":"Scan nearby radios",()->withPermission(()->{if(service.scanning)service.stopScan();else service.scan(choosing);}));space(c,8);c.addView(text(service==null?"Starting…":service.scanStatus,12,MUTED));if(service!=null)for(BluetoothDevice d:service.discovered(target)){String address=d.getAddress();addButton(c,service.discoveryLabel(d),()->withPermission(()->{service.connect(target,address);choosing=null;refreshContent();}));}addButton(c,service!=null&&service.showOtherDevices?"Show matching radios":"Show other BLE devices",()->{if(service!=null){service.showOtherDevices=!service.showOtherDevices;refreshContent();}});addButton(c,"Cancel selection",()->{if(service!=null)service.stopScan();choosing=null;refreshContent();});}
        for(RadioProfile p:RadioProfile.values()){RadioService.Session s=service==null?null:service.sessions.get(p);LinearLayout c=card(results);c.addView(text(p.title,20,WHITE));space(c,8);c.addView(text(s==null?"Starting…":s.status,13,MUTED));if(s!=null&&!s.address.isEmpty()){space(c,6);c.addView(text(s.address,12,MUTED));}addButton(c,"Choose radio",()->withPermission(()->{choosing=p;service.scan(choosing);refreshContent();}));if(s!=null&&!s.address.isEmpty())addButton(c,"Reconnect / synchronize",()->withPermission(()->service.connect(p,s.address)));if(s!=null&&!s.address.isEmpty())addButton(c,"Pair in Android",()->withPermission(()->service.pair(p)));if(s!=null&&(s.connected||s.desired))addButton(c,s.connected?"Disconnect":"Cancel connection",()->service.disconnect(p));if(s!=null)addButton(c,"Connection details",()->new AlertDialog.Builder(this).setTitle(p.title).setMessage(service.diagnostics(p)).setPositiveButton("Close",null).show());}
        if(service!=null){Switch previews=new Switch(this);previews.setText("Message previews in notifications");previews.setTextColor(WHITE);previews.setChecked(getSharedPreferences("ui",MODE_PRIVATE).getBoolean("messagePreviews",false));previews.setOnCheckedChangeListener((b,on)->getSharedPreferences("ui",MODE_PRIVATE).edit().putBoolean("messagePreviews",on).apply());results.addView(previews);}
        addButton(results,phoneEnabled()?"Disable phone location":"Enable phone location",()->{if(phoneEnabled()){getSharedPreferences("ui",MODE_PRIVATE).edit().putBoolean("gpsEnabled",false).apply();position.stop();position.location=null;refreshContent();}else requestPhonePosition();});
        addButton(results,"Export history backup",()->new AlertDialog.Builder(this).setTitle("Export private history").setMessage("The JSON file contains messages, drafts, saved nodes, favorites and local POIs. Keep it in a safe place. Radio channel secrets are not included.").setPositiveButton("Choose file",(d,w)->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"MeshCrossway-backup.json"),40)).setNegativeButton("Cancel",null).show());
        addButton(results,"Import history backup",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE),41));
        addButton(results,"Map data and software licenses",()->new AlertDialog.Builder(this).setTitle("Map attribution").setMessage("MapLibre Native (BSD-2-Clause), OpenFreeMap, © OpenMapTiles and OpenStreetMap contributors. Basemaps use the internet or downloaded areas. Your radio identities and message contents are not sent to the map provider.").setPositiveButton("OpenFreeMap",(d,w)->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://openfreemap.org/")))).setNeutralButton("Software licenses",(d,w)->showMapLicenses()).setNegativeButton("Close",null).show());
        addButton(results,"Android Bluetooth settings",()->startActivity(new Intent(Settings.ACTION_BLUETOOTH_SETTINGS)));addButton(results,"Disconnect all and stop controller",()->{if(service!=null)startService(new Intent(this,RadioService.class).setAction("STOP"));});space(results,16);results.addView(text("MeshCrossway Android 0.3.0-alpha03\nHistory is private to this app. Updating with the same signing key retains it. Uninstalling deletes app data.",12,MUTED));}
    private void showMapLicenses(){try(java.io.InputStream in=getAssets().open("MAPLIBRE_LICENSE.txt")){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);ScrollView scroll=new ScrollView(this);TextView content=text(out.toString("UTF-8"),12,WHITE);content.setPadding(dp(16),dp(12),dp(16),dp(12));content.setTextIsSelectable(true);scroll.addView(content);new AlertDialog.Builder(this).setTitle("Software licenses").setView(scroll).setPositiveButton("Close",null).show();}catch(java.io.IOException e){Toast.makeText(this,"Licenses could not be opened",Toast.LENGTH_LONG).show();}}
    private void map(){mapPanel=new MapPanel(this,new MapPanel.Host(){public List<MapPanel.Located> nodes(){return mapNodes();}public List<Poi> pois(){return service==null?Collections.emptyList():new ArrayList<>(service.history.pois);}public android.location.Location phone(){return position.location;}public boolean gpsEnabled(){return phoneEnabled();}public void gps(){requestPhonePosition();}public void node(MapPanel.Located node){if(radio(node.profile).equals(node.radio))nodeDetails(node.profile,node.node);}public void poi(String name,double lat,double lon){if(service!=null)service.history.poi(name,lat,lon);}public void deletePoi(String id){if(service!=null)service.history.deletePoi(id);}},mapStyleOverride,mapFocus);mapFocus=null;body.addView(mapPanel.root,new LinearLayout.LayoutParams(-1,-1));if(visible)mapPanel.onStart();if(resumed)mapPanel.onResume();}
    private boolean phoneEnabled(){return getSharedPreferences("ui",MODE_PRIVATE).getBoolean("gpsEnabled",false);}
    private void requestPhonePosition(){if(!position.permitted()){requestPermissions(new String[]{Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.ACCESS_FINE_LOCATION},8);return;}getSharedPreferences("ui",MODE_PRIVATE).edit().putBoolean("gpsEnabled",true).apply();if(resumed)position.start();if(position.location==null)Toast.makeText(this,"Waiting for phone location • check Android Location settings",Toast.LENGTH_LONG).show();if(mapPanel!=null)mapPanel.update();}
    private void quickReply(){ArrayList<String> replies=new ArrayList<>(Arrays.asList("OK","On my way","Need assistance"));if(position.location!=null)replies.add("Insert phone coordinates");new AlertDialog.Builder(this).setTitle("Insert into "+chatProfile.title+" draft").setItems(replies.toArray(new String[0]),(d,index)->{String text=index<3?replies.get(index):String.format(Locale.ROOT,"%.5f,%.5f",position.location.getLatitude(),position.location.getLongitude());composer.setText(text);composer.setSelection(composer.length());}).setNegativeButton("Cancel",null).show();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null||service==null)return;try{java.util.function.Consumer<String> done=error->{if(error.isEmpty()){service.reloadSavedSelection();Toast.makeText(this,request==40?"History exported":"History imported • existing messages retained",Toast.LENGTH_LONG).show();}else Toast.makeText(this,error,Toast.LENGTH_LONG).show();};if(request==40)service.history.exportBackup(getContentResolver().openOutputStream(data.getData()),done);else if(request==41)service.history.importBackup(getContentResolver().openInputStream(data.getData()),done);}catch(java.io.IOException e){Toast.makeText(this,"Could not open the selected file",Toast.LENGTH_LONG).show();}}
    private String when(long seconds){return seconds<=0?"Unknown":timestampFormat.format(new Date(seconds*1000));}
    private static String ago(long seconds){if(seconds<=0)return "last heard unknown";long delta=Math.max(0,System.currentTimeMillis()/1000-seconds);return delta<60?"heard just now":delta<3600?"heard "+delta/60+" min ago":delta<86400?"heard "+delta/3600+" h ago":"heard "+delta/86400+" days ago";}
    private TextWatcher watcher(Runnable changed){return new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){changed.run();}public void afterTextChanged(Editable e){}};}
    private void withPermission(Runnable action){if(service==null){sending=false;Toast.makeText(this,"Controller is starting; try again",Toast.LENGTH_SHORT).show();return;}ArrayList<String> missing=new ArrayList<>();if(Build.VERSION.SDK_INT>=31){for(String p:new String[]{Manifest.permission.BLUETOOTH_SCAN,Manifest.permission.BLUETOOTH_CONNECT})if(checkSelfPermission(p)!=PackageManager.PERMISSION_GRANTED)missing.add(p);}else if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)missing.add(Manifest.permission.ACCESS_FINE_LOCATION);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)missing.add(Manifest.permission.POST_NOTIFICATIONS);if(!missing.isEmpty()){pending=action;requestPermissions(missing.toArray(new String[0]),7);return;}startForegroundService(new Intent(this,RadioService.class));action.run();}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==8){if(position.permitted())requestPhonePosition();else Toast.makeText(this,"Phone location is optional; radio messaging remains available",Toast.LENGTH_LONG).show();return;}if(request==7){Runnable action=pending;pending=null;if(service!=null&&service.allowed()&&action!=null){startForegroundService(new Intent(this,RadioService.class));action.run();}else{sending=false;updateComposer();Toast.makeText(this,"Nearby devices permission is required. Draft kept.",Toast.LENGTH_LONG).show();}}}
